contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address tokenNoCode, address[] memory tos) public {
        require(tokenNoCode.code.length == 0);
        bool reverted;
        bytes memory ret;
        if (tos.length == 0) {
            try c.transfer(from, tokenNoCode, tos, 1) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        } else {
            bool ok;
            try c.transfer(from, tokenNoCode, tos, 1) returns (bool r) {
                reverted = false;
                ok = r;
            } catch {
                reverted = true;
            }
            assert(!reverted && ok);
        }
    }
    receive() external payable {}
}

