contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, uint v) public {
        require(from != address(this));
        require(address(this).code.length > 0);
        address[] memory tos = new address[](1);
        tos[0] = from;
        // this contract's fallback reverts, so every transferFrom call reverts
        bool reverted;
        try c.transfer(from, address(this), tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    fallback() external payable {
        revert("token transferFrom failed");
    }
    receive() external payable {}
}

