contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address token, address[] memory tos, uint256 v) public {
        require(tos.length == 0 || tos.length > 0);
        bool ok = true;
        if (tos.length == 0) {
            // empty list must revert
            bool reverted;
            try c.transfer(from, token, tos, v) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        } else {
            uint256 r;
            try c.transfer(from, token, tos, v) returns (bool b) { r = b ? 1 : 0; } catch { ok = false; }
            assert(!ok || r == 1);
        }
    }

    receive() external payable {}
}

