contract InvMutTest {
    C c;
    uint calls;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint v) public {
        bool reverted;
        bool ok;
        if (tos.length == 0) {
            try c.transfer(from, address(this), tos, v) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        } else {
            ok = c.transfer(from, address(this), tos, v);
            assert(ok && calls == tos.length);
